package cloud.treenewbee.quizforge.hub.ai;

import java.sql.*;
import java.time.*;
import java.security.SecureRandom;
import java.util.*;
import org.springframework.stereotype.Service;
import cloud.treenewbee.quizforge.hub.account.*;
import cloud.treenewbee.quizforge.hub.admin.AdminAccess;
import cloud.treenewbee.quizforge.hub.storage.HubDatabase;
import static cloud.treenewbee.quizforge.hub.storage.HubDatabase.*;

@Service
public class AiPoints {
    private final HubDatabase db;private final AiCrypto crypto;private final Clock clock;private final SecureRandom random=new SecureRandom();
    private final Map<String,long[]> failures=new HashMap<>();private static final String ALPHABET="0123456789ABCDEFGHJKMNPQRSTVWXYZ";
    public AiPoints(HubDatabase db,AiCrypto crypto,Clock clock){this.db=db;this.crypto=crypto;this.clock=clock;}
    public static String normalize(Object raw){if(!(raw instanceof String s)||s.length()>64)return null;String value=s.toUpperCase(Locale.ROOT).replaceAll("[\\s\\p{Z}\\uFEFF-]","").replaceFirst("^AI","").replace('O','0').replace('I','1').replace('L','1');return value.matches("[0-9A-HJKMNP-TV-Z]{16}")?value:null;}
    private DeviceException bad(String code,String message){return new DeviceException(400,code,message);}
    public long balance(Object user){return db.read(c->balance(c,user));}
    public static long balance(Connection c,Object user)throws SQLException{var row=row(c,"SELECT balance FROM ai_points WHERE user_id=?",user);return row==null?0:number(row.get("balance"));}
    private String state(Map<String,Object> row){return row.get("redeemed")!=null?"redeemed":row.get("revoked")!=null?"disabled":number(row.get("expires"))<=clock.millis()?"expired":"available";}
    public synchronized Object redeem(Object user,Object raw){long now=clock.millis();String key=user.toString();var prior=failures.get(key);if(prior!=null&&prior[1]>now&&prior[0]>=10)throw new DeviceException(429,"REDEEM_LOCKED","兑换码输错次数太多，请 1 小时后再试");String body=normalize(raw);
        var result=db.transaction(c->{if(AccountStore.blocked(c,user)||row(c,"SELECT id FROM users WHERE id=?",user)==null)throw new DeviceException(401,"HUB_LOGIN_REQUIRED","登录已失效");var code=body==null?null:row(c,"SELECT * FROM ai_redeem_codes WHERE digest=?",AccountCrypto.sha(body));if(code==null||!state(code).equals("available"))return null;long points=number(code.get("points"));if(update(c,"UPDATE ai_redeem_codes SET redeemed=?,user_id=? WHERE id=? AND redeemed IS NULL AND revoked IS NULL AND expires>?",now,user,code.get("id"),now)!=1)return null;update(c,"INSERT INTO ai_points VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET balance=balance+excluded.balance,updated=excluded.updated",user,points,now);update(c,"INSERT INTO ai_points_ledger VALUES(?,?,?,?,?,?)",UUID.randomUUID().toString(),user,points,"redeem",code.get("id"),now);return Map.of("added",points,"balance",balance(c,user));});
        if(result==null){var next=prior!=null&&prior[1]>now?prior:new long[]{0,now+3600000};next[0]++;failures.put(key,next);if(failures.size()>10000)failures.entrySet().removeIf(e->e.getValue()[1]<=now);throw bad("REDEEM_CODE_INVALID","兑换码无效、已使用或已过期");}failures.remove(key);return result;
    }
    public Object create(Map<String,Object> input,Object actor){if(input.keySet().stream().anyMatch(k->!Set.of("count","amount","expires","note").contains(k)))throw bad("AI_CODES_INVALID","字段无效");long count=AdminAccess.integer(input.get("count"),1,200,"每次生成 1–200 个兑换码"),amount=AdminAccess.integer(input.get("amount"),100,100000000,"每个兑换码的金额需为 0.01–10000 元"),expires=AdminAccess.integer(input.get("expires"),clock.millis()+1,clock.millis()+3650L*86400000,"到期时间需在今天之后、10 年以内");String note=note(input.get("note"));return db.transaction(c->{AdminAccess.current(c,actor);long seq=number(row(c,"SELECT COALESCE(MAX(seq),0) n FROM ai_redeem_codes").get("n")),now=clock.millis();var issued=new ArrayList<Map<String,Object>>();for(int i=0;i<count;i++){byte[] entropy=new byte[16];random.nextBytes(entropy);StringBuilder body=new StringBuilder();for(byte b:entropy)body.append(ALPHABET.charAt(b&31));String code="AI-"+String.join("-",body.substring(0,4),body.substring(4,8),body.substring(8,12),body.substring(12)),id=UUID.randomUUID().toString();update(c,"INSERT INTO ai_redeem_codes(id,digest,prefix,points,note,created_by,created,expires,code_cipher,seq) VALUES(?,?,?,?,?,?,?,?,?,?)",id,AccountCrypto.sha(body.toString()),code.substring(0,7),amount,note,actor,now,expires,crypto.ready()?crypto.encrypt(code,AiCrypto.CODE_AAD):null,++seq);issued.add(Map.of("id",id,"seq",seq,"code",code,"amount",amount,"expires",expires));}AdminAccess.audit(c,actor,"ai-codes-created","ai-codes",Map.of("count",count,"amount",amount,"expires",expires,"note",note));return Map.of("items",issued);});}
    private String note(Object raw){String text=raw instanceof String s?s.strip():"";if(text.codePointCount(0,text.length())>60)throw bad("AI_CODES_INVALID","备注最多 60 个字符");return text;}
    public Object codes(){return db.read(c->{var items=rows(c,"SELECT c.*,u.name AS redeemed_by FROM ai_redeem_codes c LEFT JOIN users u ON u.id=c.user_id ORDER BY c.seq DESC LIMIT 1000");var result=new ArrayList<Map<String,Object>>();for(var row:items){String code=row.get("redeemed")==null?crypto.decrypt((String)row.get("code_cipher"),AiCrypto.CODE_AAD):null;var dto=new LinkedHashMap<String,Object>();for(String field:List.of("id","seq","note","created","expires","redeemed"))dto.put(field,row.get(field));dto.put("code",code==null?row.get("prefix")+"-…":code);dto.put("full",code!=null);dto.put("amount",row.get("points"));dto.put("enabled",row.get("revoked")==null);dto.put("state",state(row));dto.put("redeemedBy",row.get("redeemed_by"));result.add(dto);}var stats=row(c,"SELECT COALESCE(SUM(points),0) total,COALESCE(SUM(CASE WHEN redeemed IS NOT NULL THEN points ELSE 0 END),0) redeemed FROM ai_redeem_codes");return Map.of("items",result,"stats",stats);});}
    public Object updateCode(String id,Map<String,Object> input,Object actor){if(input.isEmpty()||input.keySet().stream().anyMatch(k->!Set.of("note","enabled").contains(k)))throw bad("AI_CODES_INVALID","只能修改备注和启用状态");return db.transaction(c->{AdminAccess.current(c,actor);var row=row(c,"SELECT * FROM ai_redeem_codes WHERE id=?",id);if(row==null)throw new DeviceException(404,"AI_CODE_NOT_FOUND","兑换码不存在");var changed=new ArrayList<String>();if(input.containsKey("note")){String note=note(input.get("note"));if(!note.equals(row.get("note"))){update(c,"UPDATE ai_redeem_codes SET note=? WHERE id=?",note,id);changed.add("note");}}if(input.containsKey("enabled")){if(!(input.get("enabled") instanceof Boolean enabled))throw bad("AI_CODES_INVALID","请明确选择启用或停用");if(row.get("redeemed")!=null)throw new DeviceException(409,"AI_CODE_REDEEMED","兑换码已被使用，不能再启用或停用");if(enabled!=(row.get("revoked")==null)){update(c,"UPDATE ai_redeem_codes SET revoked=? WHERE id=?",enabled?null:clock.millis(),id);changed.add(enabled?"enabled":"disabled");}}if(!changed.isEmpty())AdminAccess.audit(c,actor,"ai-code-updated",id,Map.of("seq",row.get("seq"),"changed",changed));return Map.of("ok",true);});}
    public Object set(Object user,Map<String,Object> input,Object actor){if(input.keySet().stream().anyMatch(k->!Set.of("balance","reason").contains(k)))throw bad("AI_CODES_INVALID","只能修改余额");long value=AdminAccess.integer(input.get("balance"),0,10000000000L,"余额需为 0–1000000 元");String reason=AdminAccess.text(input.get("reason"),400,"请填写操作原因");if(reason.codePointCount(0,reason.length())>200)throw bad("AI_CODES_INVALID","请填写 1–200 个字的原因");db.transaction(c->{AdminAccess.current(c,actor);if(row(c,"SELECT 1 FROM users WHERE id=?",user)==null)throw new DeviceException(404,"USER_NOT_FOUND","用户不存在");long before=balance(c,user),now=clock.millis();update(c,"INSERT INTO ai_points VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET balance=excluded.balance,updated=excluded.updated",user,value,now);if(before!=value){update(c,"INSERT INTO ai_points_ledger VALUES(?,?,?,?,?,?)",UUID.randomUUID().toString(),user,value-before,"admin",reason,now);AdminAccess.audit(c,actor,"ai-balance-set",user.toString(),Map.of("before",before,"after",value,"reason",reason));}return null;});return account(user);}
    public Object account(Object user){return Map.of("balance",balance(user),"history",history(user));}
    public Object history(Object user){return db.read(c->{var list=rows(c,"SELECT l.delta,l.kind,l.ref,l.created AS at,c.prefix FROM ai_points_ledger l LEFT JOIN ai_redeem_codes c ON l.kind='redeem' AND c.id=l.ref WHERE l.user_id=? ORDER BY l.created DESC LIMIT 20",user);for(var entry:list){entry.put("note",entry.get("kind").equals("redeem")?Objects.requireNonNullElse(entry.get("prefix"),""):Objects.requireNonNullElse(entry.get("ref"),""));entry.remove("ref");entry.remove("prefix");}for(var spend:rows(c,"SELECT day,calls,points FROM official_ai_usage WHERE user_id=? AND points>0 ORDER BY day DESC LIMIT 20",user)){list.add(Map.of("kind","grading","delta",-number(spend.get("points")),"day",spend.get("day"),"calls",spend.get("calls"),"at",LocalDate.parse(spend.get("day").toString()).atTime(23,59,59).atZone(ZoneId.of("Asia/Shanghai")).toInstant().toEpochMilli()));}list.sort((a,b)->Long.compare(number(b.get("at")),number(a.get("at"))));return list.stream().limit(20).toList();});}
}
